// spec: specs/child-mode-no-levels.md §4.1 (две роли — пишет autotest-writer)
// Окно parent — режим родителя (в режим ребёнка не переводится никогда). Окно слота parent-auto — QA-R2-V, постоянно в режиме ребёнка
// (решение 08.11, #8ca267). Нового ребёнка не создаём (указание 12.11): правим пять текстовых полей существующего QA-R2-V
// метками QA-AUTO и в finally возвращаем исходные значения. Пароль и PIN не вводятся.
// Селекторы полей — по доступному имени (начало подписи из R6, research/f23704/r6-C-*.json); в браузере при записи не проверялись.
import { test, expect } from '../../fixtures';
import type { Page, Response } from '@playwright/test';
import { CHILD_SLOTS, goChildHome, openSlotPage, saveSlot } from '../child-slot.helpers';

test.describe.configure({ mode: 'serial' });

const KID = CHILD_SLOTS['QA-R2-V'];
const PROFILE = `/children/${KID.childId}`;

// Поля профиля: имя для поиска (начало подписи) и участвует ли поле в проверке утечки (заметки родителя по «מה רצוי»)
const FIELDS = [
  { key: 'speech', name: /^מאפייני דיבור/, parentNote: true },
  { key: 'difficulties', name: /^קשיים ידועים/, parentNote: true },
  { key: 'note', name: /^הערה חופשית/, parentNote: true },
  { key: 'interests', name: /^תחומי עניין/, parentNote: false },
  { key: 'goals', name: /^מטרות/, parentNote: false },
] as const;

const LEAK_MARKERS: RegExp[] = [
  /"level"\s*:\s*\d/,
  /"scale_max"\s*:\s*\d/,
  /estimated_/,
  /target_level/,
  /parent_note/,
  /speech_notes/,
  /known_difficulties/,
];

const rand6 = () =>
  Array.from({ length: 6 }, () => 'abcdefghijklmnopqrstuvwxyz'[Math.floor(Math.random() * 26)]).join('');

const field = (page: Page, name: RegExp) =>
  page.getByRole('textbox', { name }).filter({ visible: true }).first();

async function openProfile(page: Page) {
  await page.goto(PROFILE);
  await expect(page.getByText('עריכת פרופיל', { exact: true }).filter({ visible: true }).first()).toBeVisible({ timeout: 30_000 });
  await expect(field(page, FIELDS[0].name)).toBeVisible();
}

async function readFields(page: Page): Promise<Record<string, string>> {
  const out: Record<string, string> = {};
  for (const f of FIELDS) out[f.key] = await field(page, f.name).inputValue();
  return out;
}

async function fillAndSave(page: Page, values: Record<string, string>) {
  for (const f of FIELDS) await field(page, f.name).fill(values[f.key]);
  const patch = page.waitForResponse(
    (r) => r.request().method() === 'PATCH' && r.url().includes('/rest/v1/children'),
    { timeout: 30_000 },
  );
  await page.getByRole('button', { name: 'המשך', exact: true }).filter({ visible: true }).first().click();
  const resp = await patch;
  expect(resp.status(), `PATCH children: ${resp.status()}`).toBeGreaterThanOrEqual(200);
  expect(resp.status()).toBeLessThan(300);
}

test('4.1 Родитель сохраняет метки QA-AUTO в заметках/интересах/целях QA-R2-V → после перезагрузки на месте → в режиме ребёнка их нет ни в ответах, ни на экранах → исходные значения возвращены @desktop @data #eb3106 #f23704', async ({ asUser, browser }, testInfo) => {
  test.setTimeout(180_000);
  const tag = rand6();
  const marked: Record<string, string> = {};
  for (const f of FIELDS) marked[f.key] = f.parentNote ? `QA-AUTO-NOTE-${tag}-${f.key}` : `QA-AUTO-${tag}-${f.key}`;
  const noteMarker = `QA-AUTO-NOTE-${tag}`;

  // 1. Окно родителя: исходные значения
  const parent = await asUser('parent');
  await openProfile(parent);
  const original = await readFields(parent);
  testInfo.annotations.push({ type: 'data', description: `QA-R2-V: поля профиля временно = ${noteMarker}…, затем возвращаются` });

  const slot = await openSlotPage(browser, testInfo, KID);
  try {
    // 2. Сохранить метки
    await fillAndSave(parent, marked);

    // 3. После перезагрузки — метки на месте (#f23704 «נשמר בצורה עקיבה»)
    await openProfile(parent);
    await parent.reload();
    await expect(field(parent, FIELDS[0].name)).toBeVisible();
    for (const f of FIELDS) {
      await expect(field(parent, f.name), `после перезагрузки поле ${f.key}`).toHaveValue(marked[f.key]);
    }

    // 4. Окно ребёнка: все JSON-ответы на запросы с x-child-session + видимый текст экранов
    const child = slot.page;
    const bodies: { url: string; text: string }[] = [];
    const pending: Promise<void>[] = [];
    child.on('response', (resp: Response) => {
      const req = resp.request();
      if (!req.headers()['x-child-session']) return;
      if (!(resp.headers()['content-type'] ?? '').includes('json')) return;
      pending.push(
        resp
          .text()
          .then((text) => {
            bodies.push({ url: resp.url(), text });
          })
          .catch(() => undefined),
      );
    });

    await goChildHome(child, KID);
    const levelsAfterReload = child.waitForResponse((r) => r.url().includes('/rest/v1/rpc/current_levels'), { timeout: 30_000 });
    await child.reload();
    await levelsAfterReload;
    const homeTab = child.getByRole('tab', { name: 'בית' }).filter({ visible: true }).first();
    await expect(homeTab).toBeVisible();
    const screens: { name: string; text: string }[] = [];
    screens.push({ name: 'בית', text: await child.locator('body').innerText() });

    await child.getByRole('tab', { name: 'המסלול שלי' }).filter({ visible: true }).first().click();
    await expect(child.getByRole('tab', { name: 'המסלול שלי', selected: true }).filter({ visible: true }).first()).toBeVisible();
    screens.push({ name: 'המסלול שלי', text: await child.locator('body').innerText() });

    await child.goto(`/${KID.childId}/reading/pick`);
    await expect(child.getByRole('list', { name: 'סיפורים לקריאה' }).getByRole('button').first()).toBeVisible({ timeout: 30_000 });
    screens.push({ name: 'reading/pick', text: await child.locator('body').innerText() });

    await child.goto(`/${KID.childId}/writing/pick`);
    await expect(child.getByText(/קל|בינוני|מאתגר/).filter({ visible: true }).first()).toBeVisible({ timeout: 30_000 });
    screens.push({ name: 'writing/pick', text: await child.locator('body').innerText() });

    await Promise.all(pending);
    expect(bodies.length, 'ответы с x-child-session записаны').toBeGreaterThan(0);
    for (const b of bodies) {
      expect(b.text, `ответ ${b.url} содержит заметку родителя`).not.toContain(noteMarker);
      for (const m of LEAK_MARKERS) expect(b.text, `ответ ${b.url}: маркер ${m}`).not.toMatch(m);
    }
    for (const s of screens) {
      expect(s.text, `экран ${s.name} показывает заметку родителя`).not.toContain(noteMarker);
    }
  } finally {
    // 5. Вернуть исходные значения и проверить (данные QA-R2-V не испорчены)
    await saveSlot(slot.context, KID);
    await slot.context.close();
    await openProfile(parent);
    await fillAndSave(parent, original);
    await openProfile(parent);
    await parent.reload();
    await expect(field(parent, FIELDS[0].name)).toBeVisible();
    for (const f of FIELDS) {
      await expect(field(parent, f.name), `исходное значение поля ${f.key} возвращено`).toHaveValue(original[f.key]);
    }
  }
});
